#!/bin/bash
set -Eeuo pipefail
[[ $EUID -eq 0 ]] || { echo 'ERROR: run with sudo' >&2; exit 1; }
[[ $# -eq 0 || ( $# -eq 1 && $1 == --apply ) ]] || { echo 'Usage: sudo ./6-filesystem_hardening.sh [--apply]' >&2; exit 2; }
. /etc/os-release; [[ "$ID:$VERSION_ID" == ubuntu:22.04 ]] || { echo 'ERROR: Ubuntu 22.04 only' >&2; exit 2; }
mode=${1:---audit}; umask 077; logfile=$(mktemp); trap 'rm -f "$logfile"' EXIT
suid_allow=' /usr/bin/chfn /usr/bin/chsh /usr/bin/gpasswd /usr/bin/mount /usr/bin/newgrp /usr/bin/passwd /usr/bin/su /usr/bin/sudo /usr/bin/umount /usr/bin/pkexec /usr/bin/fusermount /usr/bin/fusermount3 /usr/lib/dbus-1.0/dbus-daemon-launch-helper /usr/lib/openssh/ssh-keysign /usr/lib/policykit-1/polkit-agent-helper-1 /usr/libexec/polkit-agent-helper-1 /usr/lib/snapd/snap-confine '
sgid_allow=' /usr/bin/at /usr/bin/chage /usr/bin/crontab /usr/bin/dotlockfile /usr/bin/expiry /usr/bin/locate /usr/bin/mlocate /usr/bin/ssh-agent /usr/bin/wall /usr/bin/write /usr/bin/write.ul /usr/bin/bsd-write /usr/sbin/unix_chkpwd /usr/lib/utempter/utempter /usr/lib/x86_64-linux-gnu/utempter/utempter /usr/sbin/pam_extrausers_chkpwd '
declare -A found=([SUID]=0 [SGID]=0) safe=([SUID]=0 [SGID]=0) unexpected=([SUID]=0 [SGID]=0) fixed=([SUID]=0 [SGID]=0); ww=0; wwfixed=0; sticky=0; pending=0; review=0; errors=0
if [[ $mode == --apply ]]; then getent passwd medadmin sysadmin >/dev/null || { echo 'ERROR: required admin accounts missing' >&2; exit 2; }; backup=$(mktemp -d /root/meddefense-fs.XXXXXX); cp -a /etc/fstab "$backup/fstab"; [[ ! -e /etc/cron.allow ]] || cp -a /etc/cron.allow "$backup/cron.allow"; echo "Backup/manifest: $backup"; fi
scan(){ local kind=$1 bit=$2 remove=$3 allow=$4 file; while IFS= read -r -d '' file; do ((++found[$kind])); if [[ "$allow" == *" $file "* ]]; then ((++safe[$kind])); else ((++unexpected[$kind])); if dpkg-query -S -- "$file" >/dev/null 2>&1; then printf '%s: %q [PACKAGE-OWNED: MANUAL REVIEW]\n' "$kind" "$file"; ((++review)); continue; fi; if [[ $mode == --apply ]]; then stat -c '%a %n' -- "$file" >> "$backup/modes.txt"; if chmod "$remove" -- "$file"; then ((++fixed[$kind])); else ((++errors)); fi; fi; printf '%s: %q [%s]\n' "$kind" "$file" "${mode/--/}"; fi; done < <(find / \( -path /proc -o -path /sys -o -path /dev -o -path /snap \) -prune -o -type f -perm "-$bit" -print0 2>>"$logfile"); }
echo "Mode: $mode (audit is read-only; --apply changes permissions and cron)"; echo "Snap read-only images: excluded from changes"; scan SUID 4000 u-s "$suid_allow"; scan SGID 2000 g-s "$sgid_allow"
while IFS= read -r -d '' file; do ((++ww)); if [[ $mode == --apply ]]; then stat -c '%a %n' -- "$file" >> "$backup/modes.txt"; if chmod o-w -- "$file"; then ((++wwfixed)); else ((++errors)); fi; fi; printf 'World-writable file: %q [%s]\n' "$file" "${mode/--/}"; done < <(find / \( -path /proc -o -path /sys -o -path /dev -o -path /snap \) -prune -o -type f -perm -0002 -print0 2>>"$logfile")
while IFS= read -r -d '' file; do ((++sticky)); if [[ $mode == --apply ]]; then stat -c '%a %n' -- "$file" >> "$backup/modes.txt"; chmod +t -- "$file" || ((++errors)); fi; printf 'World-writable directory without sticky bit: %q [%s]\n' "$file" "${mode/--/}"; done < <(find / \( -path /proc -o -path /sys -o -path /dev -o -path /snap \) -prune -o -type d -perm -0002 ! -perm -1000 -print0 2>>"$logfile")
mount_check(){ local d=$1 target opts good=0; target=$(findmnt -rn -T "$d" -o TARGET 2>/dev/null || :); if [[ "$target" != "$d" ]]; then echo "$d: [MANUAL] shares mount $target; not remounted"; ((++pending)); return; fi; opts=$(findmnt -rn -M "$d" -o OPTIONS); if [[ ",$opts," != *,noexec,* || ",$opts," != *,nosuid,* || ",$opts," != *,nodev,* ]]; then if [[ $mode == --apply ]]; then mount -o remount,noexec,nosuid,nodev "$d" || ((++errors)); fi; fi; opts=$(findmnt -rn -M "$d" -o OPTIONS); if [[ ",$opts," == *,noexec,* && ",$opts," == *,nosuid,* && ",$opts," == *,nodev,* ]]; then echo "$d: noexec,nosuid,nodev [OK]"; good=1; else echo "$d: [NEEDS HARDENING]"; ((++pending)); fi; if [[ $mode == --apply && $good -eq 1 ]]; then if awk -v d="$d" '$1 !~ /^#/ && $2 == d {found=1} END {exit !found}' /etc/fstab; then awk -v d="$d" '$1 !~ /^#/ && $2 == d {if ($4 !~ /(^|,)noexec(,|$)/) $4=$4",noexec"; if ($4 !~ /(^|,)nosuid(,|$)/) $4=$4",nosuid"; if ($4 !~ /(^|,)nodev(,|$)/) $4=$4",nodev"} {print}' /etc/fstab > "$backup/newfstab" && cat "$backup/newfstab" > /etc/fstab; elif [[ $d == /dev/shm ]]; then printf 'tmpfs /dev/shm tmpfs defaults,noexec,nosuid,nodev 0 0\n' >> /etc/fstab; else echo "$d: [MANUAL] no fstab entry to persist options"; ((++pending)); fi; fi; }
mount_check /tmp; mount_check /var/tmp; mount_check /dev/shm
if [[ $mode == --apply ]]; then printf 'root\nmedadmin\nsysadmin\n' > "$backup/cron.allow.new"; if getent group crontab >/dev/null; then install -o root -g crontab -m 0640 "$backup/cron.allow.new" /etc/cron.allow; else install -o root -g root -m 0644 "$backup/cron.allow.new" /etc/cron.allow; fi; echo 'Cron access: root, medadmin, sysadmin [APPLIED]'; elif [[ -f /etc/cron.allow && $(stat -c "%U:%G %a" /etc/cron.allow) == "root:crontab 640" && $(cat /etc/cron.allow) == $'root\nmedadmin\nsysadmin' ]]; then echo 'Cron access: root, medadmin, sysadmin [OK]'; else echo 'Cron access: root, medadmin, sysadmin [NEEDS HARDENING]'; fi
printf 'Found %d SUID binaries | Whitelisted: %d | Non-whitelisted: %d | Removed: %d\n' "${found[SUID]}" "${safe[SUID]}" "${unexpected[SUID]}" "${fixed[SUID]}"
printf 'Found %d SGID binaries | Whitelisted: %d | Non-whitelisted: %d | Removed: %d\n' "${found[SGID]}" "${safe[SGID]}" "${unexpected[SGID]}" "${fixed[SGID]}"
printf 'World-writable files: %d | Fixed: %d | Unsafe directories: %d | Mount tasks pending: %d | Package review: %d | Errors: %d\n' "$ww" "$wwfixed" "$sticky" "$pending" "$review" "$errors"
[[ ! -s $logfile ]] || { echo 'WARNING: filesystem traversal reported errors:' >&2; cat "$logfile" >&2; ((++errors)); }
if [[ $mode == --apply && ( $errors -ne 0 || $pending -ne 0 || $review -ne 0 ) ]]; then echo 'PARTIAL: review errors/manual mount tasks; do not mark compliant' >&2; exit 1; fi
